import React from 'react'
import LoginForm, { Props } from '../../components/LoginForm'
import { Card, Row, Col } from "antd";
import { useStoreState } from 'state'


const LoginOne = (props: Props) => {
	const theme = useStoreState(state => state.theme.currentTheme)
	
	const backgroundStyle = {
		background: theme === 'dark'
			? 'linear-gradient(to right, #283c86, #45a247)'
			: 'linear-gradient(to right, #11998e, #38ef7d)'
	}

	return (
		<div className="h-100" style={backgroundStyle}>
			<div className="container d-flex flex-column justify-content-center h-100">
				<Row justify="center">
					<Col xs={20} sm={20} md={20} lg={7}>
						<Card>
							<div className="my-4">
								<div className="text-center">
									<img className="img-fluid" src={`/img/${theme === 'light' ? 'logo-login.png': 'logo-white.png'}`} alt="" />
									{/* <p style={{ marginTop: 15 }} >Don't have an account yet? <a href="/auth/register-1">Sign Up</a></p> */}
								</div>
								<Row justify="center">
									<Col xs={24} sm={24} md={20} lg={20}>
										<LoginForm {...props} />
									</Col>
								</Row>
							</div>
						</Card>
					</Col>
				</Row>
			</div>
		</div>
	)
}

export default LoginOne
